mapper.select:
SELECT cl.*, od.context, od.vedio, od.file, od.id as objectDataId, od.total_watch_time, od.watch_time FROM chapter_list cl LEFT JOIN object_data od ON cl.chapter_code = od.chapter_code
1 = 1
and cl.object_code = #{objectCode}
and cl.chapter_code = #{chapterCode}
order by cl.create_time
